/** Request-scoped runtime configuration; platform bindings are generated by Wrangler. */
export type RuntimeEnv = Partial<Omit<Cloudflare.Env, 'ALLOWED_ORIGIN' | 'HYPERDRIVE'>> & {
  GEMINI_API_KEY?: string;
  FIREBASE_PROJECT_ID?: string;
  HYPERDRIVE?: Pick<Hyperdrive, 'connectionString'>;
  DATA_ENCRYPTION_KEY?: string;
  DATA_ENCRYPTION_KEY_VERSION?: string;
  IP_HASH_SALT?: string;
  SAFE_BROWSING_API_KEY?: string;
  ADMIN_SECRET?: string;
  ALLOWED_ORIGIN?: string;
  DEMO_MODE?: string;
};

export type UserIdentity = { id: string; displayName: string; demo: boolean };

export function isDemoMode(env: RuntimeEnv): boolean {
  return env.DEMO_MODE === 'true' || !env.FIREBASE_PROJECT_ID || !env.HYPERDRIVE;
}
